```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', line => {
    lines.push(line);
    if (lines.length === 2) {
        const n = parseInt(lines[0]);
        const str = lines[1];
        let count = 0;
        for (let i = 0; i < n; i++) {
            if (str[i] === 'x' && str[i + 1] === 'x' && str[i + 2] === 'x') {
                count++;
            }
        }
        console.log(count);
        rl.close();
    }
});
```

